(function(){
  /* модалка «Отправить ТЗ» */
  var m=document.getElementById('lead-modal'), f=document.getElementById('lead-form'),
      body=document.getElementById('lead-body'), done=document.getElementById('lead-done');
  function open(t,c,msg){ if(!m)return; if(t)document.getElementById('lead-title').textContent=t; if(c)document.getElementById('lead-ctx').textContent=c;
    if(f)f.reset(); var fl=document.getElementById('file-label'); if(fl)fl.textContent='Прикрепить ТЗ / спецификацию';
    if(f&&f.message&&msg)f.message.value=msg;
    if(body)body.hidden=false; if(done)done.hidden=true; m.hidden=false; document.documentElement.style.overflow='hidden'; }
  window.dsOpenLead=open;
  function close(){ if(m){m.hidden=true; document.documentElement.style.overflow='';} }
  document.addEventListener('click',function(e){
    var t=e.target.closest?e.target.closest('[data-lead]'):null;
    if(t){ e.preventDefault(); closeMenu(); open(t.getAttribute('data-lead-title'),t.getAttribute('data-lead-ctx')); return; }
    if(e.target.closest&&e.target.closest('[data-close]')) close();
  });
  document.addEventListener('keydown',function(e){ if(e.key==='Escape') close(); });
  var lf=document.getElementById('lead-file');
  if(lf)lf.addEventListener('change',function(){ var fl=document.getElementById('file-label'); if(fl)fl.textContent=(lf.files&&lf.files.length)?lf.files[0].name:'Прикрепить ТЗ / спецификацию'; });
  if(f)f.addEventListener('submit',function(e){ e.preventDefault(); if(!f.contact.value.trim()){f.contact.focus();return;}
    /* TODO: подключить реальную отправку (Formspree / e-mail / Telegram) */
    if(body)body.hidden=true; if(done)done.hidden=false; });

  /* бургер */
  var nl=document.getElementById('nav-links'), nb=document.getElementById('nav-burger');
  window.closeMenu=function(){ if(nl)nl.classList.remove('open'); if(nb)nb.setAttribute('aria-expanded','false'); };
  if(nb)nb.addEventListener('click',function(){ var o=nl.classList.toggle('open'); nb.setAttribute('aria-expanded',o?'true':'false'); });

  /* мега-меню «Каталог»: на мобиле тап разворачивает список */
  var catItem=document.getElementById('cat-item');
  if(catItem){ var trig=catItem.querySelector('.nav-mega-trigger');
    if(trig)trig.addEventListener('click',function(e){ if(window.innerWidth<=1024){ e.preventDefault(); catItem.classList.toggle('open'); } }); }

  /* ранжирование результатов поиска: целевой запрос (название/направление) — выше,
     вторичные совпадения (только в характеристиках/описании) — ниже */
  function qnrm(s){return String(s||'').toLowerCase().replace(/[‐‑‒–—]/g,'-');}
  function qscore(name,dir,code,kw,v){
    name=qnrm(name);dir=qnrm(dir);code=qnrm(code);kw=qnrm(kw);
    var s=0;
    if((' '+name+' ').indexOf(' '+v+' ')>=0) s+=140;       // целое слово в названии
    else if(name.indexOf(v)===0) s+=120;                   // название начинается с запроса
    else if(name.indexOf(v)>=0) s+=100;                    // запрос входит в название
    if(code.indexOf(v)>=0) s+=55;                          // код изделия
    if(dir.indexOf(v)>=0) s+=85;                           // направление — тоже целевое
    if(kw.indexOf(v)>=0) s+= (s>0?4:12);                   // только в ТТХ/описании — вторичное
    if(s===0){                                             // компактный матч: «RL 1001» → «DS‑RL1001»
      var cv=v.replace(/[s-]/g,'');
      if(cv.length>=3 && (name+' '+code+' '+kw).replace(/[s-]/g,'').indexOf(cv)>=0) s+=90;
    }
    return s;
  }

  /* поиск по каталогу */
  var q=document.getElementById('cat-q');
  if(q){
    var wrap=document.getElementById('cat-grid-wrap'), res=document.getElementById('cat-results');
    function nrm(s){return s.toLowerCase().replace(/[‐‑‒–—]/g,'-');}
    q.addEventListener('keydown',function(e){ if(e.key==='Enter'){ e.preventDefault(); var qv=q.value.trim(); if(qv) location.href=BASE+'search/?q='+encodeURIComponent(qv); } });
    q.addEventListener('input',function(){
      var v=nrm(q.value.trim());
      if(!v){ if(wrap)wrap.style.display=''; if(res){res.style.display='none';res.innerHTML='';} return; }
      var hits=(window.QT_INDEX||[]).map(function(p,ix){return {p:p,ix:ix,sc:qscore(p.n,p.d,p.c,p.k,v)};})
        .filter(function(o){return o.sc>0;})
        .sort(function(a,b){return b.sc-a.sc || a.ix-b.ix;})
        .map(function(o){return o.p;});
      if(wrap)wrap.style.display='none'; if(res)res.style.display='';
      if(res)res.innerHTML = hits.length
        ? '<p class="muted" style="margin:0 0 16px;font-size:14px">Найдено: '+hits.length+'</p><div class="prod-grid">'+hits.map(function(p){return '<a class="pcard" href="'+BASE+'product/'+p.s+'/"><div class="pc-code">'+p.c+'</div><h3>'+p.n+'</h3><p class="pc-desc">'+p.d+'</p><span class="pc-go">Подробнее →</span></a>';}).join('')+'</div>'
        : (function(){var Q=q.value.trim().replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');return '<div class="cat-empty"><div class="cat-empty-ic"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="11" cy="11" r="7"/><path d="M21 21l-3.5-3.5M8 11h6"/></svg></div><h3>Ничего не найдено по запросу «'+Q+'»</h3><p>Не нашли нужный прибор в каталоге? Опишите задачу или пришлите ТЗ — подберём из полного ассортимента, найдём аналог или разработаем под ваши требования. Ответим в течение рабочего дня.</p><div class="cat-empty-cta"><button class="btn btn-primary" data-lead data-lead-title="Подбор оборудования: '+Q+'" data-lead-ctx="Подбор оборудования">Отправить ТЗ на подбор</button><a class="btn btn-ghost" href="https://wa.me/79962404050" target="_blank" rel="noopener">WhatsApp</a><a class="btn btn-ghost" href="tel:+79962404050">Позвонить</a></div></div>';})();
    });
  }

  /* фасетные фильтры на странице направления */
  var facetsEl=document.getElementById('facets');
  if(facetsEl){
    var dgrid=document.getElementById('dir-grid');
    var fcards=[].slice.call(dgrid.querySelectorAll('.pcard'));
    var fcount=document.getElementById('fcount'), fword=document.getElementById('fword'), fempty=document.getElementById('fempty');
    var alCard=dgrid.querySelector('.pcard[href*="ds-agilelight"]');
    var alBase=alCard?alCard.getAttribute('href').split('?')[0]:null;
    function fplural(n){n=Math.abs(n)%100;var n1=n%10;if(n>10&&n<20)return 'позиций';if(n1>1&&n1<5)return 'позиции';if(n1===1)return 'позиция';return 'позиций';}
    function applyFacets(){
      var sel={};
      facetsEl.querySelectorAll('input:checked').forEach(function(i){var k=i.getAttribute('data-fkey');(sel[k]=sel[k]||[]).push(i.value);});
      var keys=Object.keys(sel), shown=0;
      fcards.forEach(function(c){
        var ok=keys.every(function(k){
          var vals=(c.getAttribute('data-'+k)||'').split('|');
          return sel[k].some(function(v){return vals.indexOf(v)>=0;});
        });
        c.style.display=ok?'':'none';
        if(ok){shown++; c.classList.add('in');}
      });
      /* «полный ряд» AgileLight: прокидываем выбранные оси в ссылку, чтобы его таблица открылась уже отфильтрованной */
      if(alCard){var ax=sel.axes||[]; alCard.setAttribute('href', ax.length? alBase+'?axes='+encodeURIComponent(ax.join(',')) : alBase);}
      if(fcount)fcount.textContent=shown;
      if(fword)fword.textContent=fplural(shown);
      if(fempty)fempty.hidden=shown>0;
    }
    facetsEl.addEventListener('change',applyFacets);
    var fclr=document.getElementById('facets-clear');
    if(fclr)fclr.addEventListener('click',function(){facetsEl.querySelectorAll('input:checked').forEach(function(i){i.checked=false;});applyFacets();});
    var ftog=document.getElementById('facets-toggle');
    if(ftog)ftog.addEventListener('click',function(){facetsEl.classList.toggle('open');});
  }

  /* фильтр строк большой таблицы «полного ряда» по числу осей (напр. AgileLight) */
  var tf=document.querySelector('[data-axisfilter]');
  if(tf){
    var ttable=tf.parentNode.querySelector('table.specs-t');
    var trows=ttable?[].slice.call(ttable.querySelectorAll('tbody tr')):[];
    function setAx(ax){
      var btns=tf.querySelectorAll('.tf-b');
      for(var i=0;i<btns.length;i++) btns[i].classList.toggle('active',btns[i].getAttribute('data-ax')===ax);
      trows.forEach(function(r){var ra=r.getAttribute('data-axis')||''; r.style.display=(!ax||ra===ax)?'':'none';});
    }
    tf.addEventListener('click',function(e){var b=e.target.closest?e.target.closest('.tf-b'):null; if(b)setAx(b.getAttribute('data-ax'));});
    try{
      var pa=(new URLSearchParams(location.search)).get('axes');
      if(pa){var parts=pa.split(','); if(parts.length===1 && ['одноосный','двухосный','трёхосный'].indexOf(parts[0])>=0) setAx(parts[0]);}
    }catch(e){}
  }

  /* глобальный поиск в шапке */
  var nq=document.getElementById('nav-q');
  if(nq){
    var nr=document.getElementById('nav-results');
    function nnrm(s){return String(s||'').toLowerCase().replace(/[‐‑‒–—]/g,'-');}
    function nesc(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}
    var NAV=(window.QT_NAV||[]).map(function(x){return {t:x.t,u:x.u,g:x.g,i:x.i,k:nnrm(x.t+' '+(x.k||'')+' '+(x.g||''))};});
    var PRD=(window.QT_INDEX||[]).map(function(p){return {t:p.n,u:BASE+'product/'+p.s+'/',g:p.d+' · '+p.c,i:p.i,k:nnrm(p.n+' '+p.c+' '+p.d+' '+p.k)};});
    var ALL=NAV.concat(PRD), idx=-1;
    function nthumb(x){ return x.i ? '<span class="nr-ph" style="background-image:url('+x.i+')"></span>'
      : '<span class="nr-ph"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><rect x="3" y="3" width="18" height="18" rx="4"/><path d="M3 9h18M9 21V9"/></svg></span>'; }
    function closeN(){ if(nr){nr.classList.remove('open');nr.innerHTML='';} idx=-1; nq.setAttribute('aria-expanded','false'); }
    function upd(items){ for(var i=0;i<items.length;i++) items[i].classList.toggle('active',i===idx); if(idx>=0&&items[idx]) items[idx].scrollIntoView({block:'nearest'}); }
    function render(){
      var v=nnrm(nq.value.trim());
      if(!v){ closeN(); return; }
      var hits=ALL.map(function(x,ix){return {x:x,ix:ix,sc:qscore(x.t,x.g,'',x.k,v)};})
        .filter(function(o){return o.sc>0;})
        .sort(function(a,b){return b.sc-a.sc || a.ix-b.ix;})
        .slice(0,10).map(function(o){return o.x;});
      if(!hits.length){ nr.innerHTML='<div class="nav-empty">Ничего не найдено. <span class="nav-empty-cta" data-lead data-lead-title="Подбор оборудования" data-lead-ctx="Подбор оборудования">Отправить ТЗ на подбор →</span></div>'; }
      else nr.innerHTML=hits.map(function(x){return '<a class="nav-res" role="option" href="'+x.u+'">'+nthumb(x)+'<span class="nr-txt"><span class="nr-t">'+nesc(x.t)+'</span><span class="nr-g">'+nesc(x.g)+'</span></span></a>';}).join('');
      nr.classList.add('open'); nq.setAttribute('aria-expanded','true'); idx=-1;
    }
    nq.addEventListener('input',render);
    nq.addEventListener('focus',function(){ if(nq.value.trim()) render(); });
    nq.addEventListener('keydown',function(e){
      var items=nr?nr.querySelectorAll('.nav-res'):[];
      if(e.key==='ArrowDown'){ e.preventDefault(); if(items.length){ idx=(idx+1)%items.length; upd(items);} }
      else if(e.key==='ArrowUp'){ e.preventDefault(); if(items.length){ idx=(idx-1+items.length)%items.length; upd(items);} }
      else if(e.key==='Enter'){ e.preventDefault();
        if(idx>=0 && items[idx]){ items[idx].click(); }
        else { var qv=nq.value.trim(); if(qv) location.href=BASE+'search/?q='+encodeURIComponent(qv); }
      }
      else if(e.key==='Escape'){ closeN(); nq.blur(); }
    });
    document.addEventListener('click',function(e){ if(!(e.target.closest&&e.target.closest('.nav-search'))) closeN(); });
  }

  /* страница результатов поиска /search/?q= — клиентский рендер + фасет «Направление» */
  var sroot=document.getElementById('search-root');
  if(sroot){
    var sIDX=window.QT_INDEX||[];
    var sInput=document.getElementById('search-q'), sGrid=document.getElementById('search-grid'), sFacets=document.getElementById('search-facets');
    var sCount=document.getElementById('search-count'), sWord=document.getElementById('search-word');
    var sEmpty=document.getElementById('search-empty'), sEmptyH=document.getElementById('search-empty-h'), sH1=document.getElementById('search-h1'), sPanel=document.getElementById('search-panel');
    var curRanked=[], dirFilter=[];
    function sPlural(n){n=Math.abs(n)%100;var n1=n%10;if(n>10&&n<20)return 'результатов';if(n1>1&&n1<5)return 'результата';if(n1===1)return 'результат';return 'результатов';}
    function getQ(){try{return (new URLSearchParams(location.search)).get('q')||'';}catch(e){return '';}}
    function cardHTML(p){
      return '<a class="pcard" data-dir="'+esc2(p.d)+'" href="'+BASE+'product/'+p.s+'/">'+
        (p.i?'<div class="pc-photo"><img loading="lazy" src="'+p.i+'" alt="'+esc2(p.n)+'"></div>':'')+
        '<div class="pc-code">'+esc2(p.c)+'</div><h3>'+esc2(p.n)+'</h3>'+
        '<div class="pc-tag-dir">'+esc2(p.d)+'</div><span class="pc-go">Подробнее →</span></a>';
    }
    function applyDir(){
      var shown=0;
      [].slice.call(sGrid.querySelectorAll('.pcard')).forEach(function(c){
        var ok=!dirFilter.length || dirFilter.indexOf(c.getAttribute('data-dir'))>=0;
        c.style.display=ok?'':'none'; if(ok){shown++;c.classList.add('in');}
      });
      sCount.textContent=shown; sWord.textContent=sPlural(shown); sEmpty.hidden=shown>0;
    }
    var sLayout=sPanel.parentNode;
    function buildFacets(ranked){
      var counts={}, ord=[];
      ranked.forEach(function(p){ if(!(p.d in counts)){counts[p.d]=0;ord.push(p.d);} counts[p.d]++; });
      if(ord.length<2){ sPanel.style.display='none'; sFacets.innerHTML=''; if(sLayout)sLayout.classList.add('no-facets'); return; }
      sPanel.style.display=''; if(sLayout)sLayout.classList.remove('no-facets');
      sFacets.innerHTML=ord.map(function(d){return '<label class="fopt"><input type="checkbox" value="'+esc2(d)+'"><span>'+esc2(d)+' <span class="fopt-n">'+counts[d]+'</span></span></label>';}).join('');
    }
    function run(query){
      var v=qnrm(query.trim());
      curRanked = v ? sIDX.map(function(p,ix){return {p:p,ix:ix,sc:qscore(p.n,p.d,p.c,p.k,v)};}).filter(function(o){return o.sc>0;}).sort(function(a,b){return b.sc-a.sc||a.ix-b.ix;}).map(function(o){return o.p;}) : [];
      dirFilter=[];
      if(sH1)sH1.textContent = query.trim()? 'Результаты по запросу «'+query.trim()+'»' : 'Поиск по каталогу';
      if(sEmptyH)sEmptyH.textContent = query.trim()? 'Ничего не найдено по запросу «'+query.trim()+'»' : 'Введите запрос в строку выше';
      sGrid.innerHTML=curRanked.map(pcardJS).join('');
      buildFacets(curRanked); applyDir();
      if(window.dsDecorate)window.dsDecorate(sGrid);
    }
    sFacets.addEventListener('change',function(){ dirFilter=[].slice.call(sFacets.querySelectorAll('input:checked')).map(function(i){return i.value;}); applyDir(); });
    var sClr=document.getElementById('search-clear');
    if(sClr)sClr.addEventListener('click',function(){[].slice.call(sFacets.querySelectorAll('input:checked')).forEach(function(i){i.checked=false;});dirFilter=[];applyDir();});
    var sTog=document.getElementById('search-toggle');
    if(sTog)sTog.addEventListener('click',function(){sPanel.classList.toggle('open');});
    if(sInput)sInput.addEventListener('keydown',function(e){ if(e.key==='Enter'){ e.preventDefault(); var q=sInput.value.trim(); try{history.replaceState(null,'',BASE+'search/'+(q?('?q='+encodeURIComponent(q)):''));}catch(_){} run(q); } });
    var q0=getQ(); if(sInput)sInput.value=q0; run(q0);
  }

  /* ===== Избранное / Сравнение / Корзина (localStorage) ===== */
  function esc2(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}
  var PBY={}; (window.QT_INDEX||[]).forEach(function(p){PBY[p.s]=p;});
  var CMP_MAX=4;
  function plur(n,a,b,c){n=Math.abs(n)%100;var n1=n%10;if(n>10&&n<20)return c;if(n1>1&&n1<5)return b;if(n1===1)return a;return c;}
  var HEART_S='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><path d="M12 20.5l-1.4-1.3C5.7 14.9 3 12.4 3 9.2 3 6.9 4.8 5 7.1 5c1.4 0 2.8.7 3.6 1.8l1.3 1.7 1.3-1.7C14.1 5.7 15.5 5 16.9 5 19.2 5 21 6.9 21 9.2c0 3.2-2.7 5.7-7.6 10z"/></svg>';
  var CMP_S='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><path d="M4 20V10M10 20V4M16 20v-7M22 20H2"/></svg>';
  function emit(){ try{document.dispatchEvent(new CustomEvent('ds-store'));}catch(e){var ev=document.createEvent('Event');ev.initEvent('ds-store',true,true);document.dispatchEvent(ev);} }
  var Store={
    read:function(k){try{return JSON.parse(localStorage.getItem(k))||[];}catch(e){return [];}},
    write:function(k,v){try{localStorage.setItem(k,JSON.stringify(v));}catch(e){} emit();},
    fav:function(){return this.read('ds_fav');}, cmp:function(){return this.read('ds_cmp');}, cart:function(){return this.read('ds_cart');},
    hasFav:function(s){return this.fav().indexOf(s)>=0;}, hasCmp:function(s){return this.cmp().indexOf(s)>=0;},
    inCart:function(s){return this.cart().some(function(i){return i.s===s;});},
    toggleFav:function(s){var a=this.fav(),i=a.indexOf(s);if(i>=0)a.splice(i,1);else a.push(s);this.write('ds_fav',a);},
    toggleCmp:function(s){var a=this.cmp(),i=a.indexOf(s);if(i>=0){a.splice(i,1);this.write('ds_cmp',a);return;}if(a.length>=CMP_MAX){alert('В сравнении максимум '+CMP_MAX+' прибора. Уберите один, чтобы добавить новый.');return;}a.push(s);this.write('ds_cmp',a);},
    cartToggle:function(s){var a=this.cart();if(a.some(function(i){return i.s===s;})){this.write('ds_cart',a.filter(function(i){return i.s!==s;}));return;}a.push({s:s,q:1});this.write('ds_cart',a);},
    cartSet:function(s,q){var a=this.cart();for(var i=0;i<a.length;i++){if(a[i].s===s){if(q<=0)a.splice(i,1);else a[i].q=q;break;}}this.write('ds_cart',a);},
    clear:function(k){this.write(k,[]);},
    counts:function(){return {fav:this.fav().length,cmp:this.cmp().length,cart:this.cart().reduce(function(t,i){return t+(i.q||1);},0)};}
  };
  window.DSStore=Store;

  function pcardJS(p){
    return '<a class="pcard" data-dir="'+esc2(p.d)+'" href="'+BASE+'product/'+p.s+'/">'+
      (p.i?'<div class="pc-photo"><img loading="lazy" src="'+p.i+'" alt="'+esc2(p.n)+'"></div>':'')+
      '<div class="pc-code">'+esc2(p.c)+'</div><h3>'+esc2(p.n)+'</h3>'+
      '<div class="pc-tag-dir">'+esc2(p.d)+'</div><span class="pc-go">Подробнее →</span></a>';
  }
  function decorateCards(root){
    [].slice.call((root||document).querySelectorAll('.pcard')).forEach(function(c){
      if(c.getAttribute('data-tooled'))return;
      var m=(c.getAttribute('href')||'').match(/product\/([a-z0-9-]+)\/?(?:\?|$)/); if(!m)return;
      var s=m[1]; c.setAttribute('data-tooled','1');
      var box=document.createElement('div'); box.className='pc-tools';
      box.innerHTML='<button type="button" class="pc-tbtn" data-act="fav" data-slug="'+s+'" aria-label="В избранное" title="В избранное">'+HEART_S+'</button>'+
                    '<button type="button" class="pc-tbtn" data-act="cmp" data-slug="'+s+'" aria-label="В сравнение" title="В сравнение">'+CMP_S+'</button>';
      c.appendChild(box);
    });
    updStates();
  }
  window.dsDecorate=decorateCards;

  function updBadges(){
    var c=Store.counts();
    [['badge-fav',c.fav],['badge-cmp',c.cmp],['badge-cart',c.cart]].forEach(function(x){var el=document.getElementById(x[0]);if(el){el.textContent=x[1];el.hidden=x[1]<=0;}});
  }
  function updStates(){
    [].slice.call(document.querySelectorAll('[data-act]')).forEach(function(b){
      var s=b.getAttribute('data-slug'),act=b.getAttribute('data-act');if(!s)return;
      var on=act==='fav'?Store.hasFav(s):act==='cmp'?Store.hasCmp(s):Store.inCart(s);
      b.classList.toggle('active',on);
      var t=b.querySelector('.pa-t');if(t)t.textContent=act==='fav'?(on?'В избранном':'В избранное'):act==='cmp'?(on?'В сравнении':'В сравнение'):(on?'В корзине':'В корзину');
    });
  }

  /* клики по кнопкам действий (страница товара + карточки) */
  document.addEventListener('click',function(e){
    var b=e.target.closest?e.target.closest('[data-act]'):null; if(!b)return;
    e.preventDefault(); e.stopPropagation();
    var s=b.getAttribute('data-slug'),act=b.getAttribute('data-act');if(!s)return;
    if(act==='fav')Store.toggleFav(s); else if(act==='cmp')Store.toggleCmp(s); else if(act==='cart')Store.cartToggle(s);
  });
  /* количество в корзине */
  document.addEventListener('click',function(e){
    var b=e.target.closest?e.target.closest('[data-cq]'):null; if(!b)return;
    var s=b.getAttribute('data-slug'),op=b.getAttribute('data-cq');
    var it=Store.cart().filter(function(i){return i.s===s;})[0],q=it?it.q:0;
    if(op==='inc')Store.cartSet(s,q+1); else if(op==='dec')Store.cartSet(s,q-1); else Store.cartSet(s,0);
  });

  /* рендер страниц */
  function renderFav(){
    var grid=document.getElementById('fav-grid'); if(!grid)return;
    var items=Store.fav().map(function(s){return PBY[s];}).filter(Boolean);
    document.getElementById('fav-count').textContent=items.length;
    document.getElementById('fav-word').textContent=plur(items.length,'позиция','позиции','позиций');
    document.getElementById('fav-empty').hidden=items.length>0;
    grid.innerHTML=items.map(pcardJS).join(''); decorateCards(grid);
  }
  function renderCmp(){
    var wrap=document.getElementById('cmp-table'); if(!wrap)return;
    var items=Store.cmp().map(function(s){return PBY[s];}).filter(Boolean);
    document.getElementById('cmp-count').textContent=items.length;
    document.getElementById('cmp-word').textContent=plur(items.length,'позиция','позиции','позиций');
    document.getElementById('cmp-empty').hidden=items.length>0; wrap.style.display=items.length?'':'none';
    if(!items.length){wrap.innerHTML='';return;}
    function rowH(){return '<tr><th class="cmp-corner"></th>'+items.map(function(p){return '<th><button type="button" class="cmp-x" data-act="cmp" data-slug="'+p.s+'" aria-label="Убрать">✕</button><a class="cmp-hd" href="'+BASE+'product/'+p.s+'/">'+(p.i?'<span class="cmp-ph" style="background-image:url('+p.i+')"></span>':'<span class="cmp-ph"></span>')+'<span class="cmp-nm">'+esc2(p.n)+'</span></a></th>';}).join('')+'</tr>';}
    function row(label,vals){return '<tr><td class="cmp-k">'+label+'</td>'+vals.map(function(v){return '<td>'+v+'</td>';}).join('')+'</tr>';}
    var body=row('Код',items.map(function(p){return '<span class="cmp-code">'+esc2(p.c)+'</span>';}))+
             row('Направление',items.map(function(p){return esc2(p.d);}))+
             row('Ключевые параметры',items.map(function(p){return (p.ch&&p.ch.length)?p.ch.map(function(x){return '<span class="cmp-chip">'+esc2(x)+'</span>';}).join(''):'—';}));
    wrap.innerHTML='<div class="cmp-scroll"><table class="cmp-t"><thead>'+rowH()+'</thead><tbody>'+body+'</tbody></table></div>';
  }
  function renderCart(){
    var box=document.getElementById('cart-items'); if(!box)return;
    var items=Store.cart().map(function(i){return {p:PBY[i.s],q:i.q};}).filter(function(x){return x.p;});
    var layout=document.getElementById('cart-layout'),empty=document.getElementById('cart-empty');
    document.getElementById('cart-n').textContent=items.reduce(function(t,x){return t+x.q;},0);
    if(!items.length){layout.style.display='none';empty.hidden=false;box.innerHTML='';return;}
    layout.style.display='';empty.hidden=true;
    box.innerHTML=items.map(function(x){var p=x.p;return '<div class="cart-item">'+
      (p.i?'<a class="ci-ph" href="'+BASE+'product/'+p.s+'/" style="background-image:url('+p.i+')"></a>':'<span class="ci-ph"></span>')+
      '<div class="ci-main"><a class="ci-nm" href="'+BASE+'product/'+p.s+'/">'+esc2(p.n)+'</a><div class="ci-code">'+esc2(p.c)+' · '+esc2(p.d)+'</div></div>'+
      '<div class="ci-qty"><button type="button" data-cq="dec" data-slug="'+p.s+'" aria-label="−">−</button><span>'+x.q+'</span><button type="button" data-cq="inc" data-slug="'+p.s+'" aria-label="+">+</button></div>'+
      '<button type="button" class="ci-x" data-cq="rm" data-slug="'+p.s+'" aria-label="Удалить">✕</button></div>';}).join('');
  }
  window.dsRerender=function(){ renderFav(); renderCmp(); renderCart(); };

  /* кнопки на страницах инструментов */
  var cs=document.getElementById('cart-submit');
  if(cs)cs.addEventListener('click',function(){
    var items=Store.cart().map(function(i){var p=PBY[i.s];return p?('• '+p.n+' ('+p.c+') — '+i.q+' шт.'):null;}).filter(Boolean);
    if(!items.length)return;
    window.dsOpenLead('Запрос по корзине','Корзина · '+items.length+' поз.','Прошу подготовить расчёт и КП по позициям:\n'+items.join('\n'));
  });
  var cclr=document.getElementById('cart-clear'); if(cclr)cclr.addEventListener('click',function(){ if(confirm('Очистить корзину?'))Store.clear('ds_cart'); });
  var xclr=document.getElementById('cmp-clear'); if(xclr)xclr.addEventListener('click',function(){ Store.clear('ds_cmp'); });

  document.addEventListener('ds-store',function(){ updBadges(); updStates(); window.dsRerender(); });
  /* старт */
  updBadges(); decorateCards(document); window.dsRerender();

  /* hero-canvas: «оптический гироскоп» — кольца + встречные световые импульсы (эффект Саньяка) */
  var cvs=document.getElementById('field');
  if(cvs){
    var reduce=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    var cx2=cvs.getContext('2d'), W,H,DPR,RAF,T=0, CY='69,195,180';
    var rings=[0.50,0.68,0.86,1.03], rAlpha=[0.16,0.30,0.20,0.10];
    var pulses=[{r:0.68,a:0,d:1,s:0.010},{r:0.68,a:Math.PI,d:-1,s:0.010},{r:0.86,a:1.1,d:1,s:0.0072},{r:0.50,a:2.4,d:-1,s:0.013},{r:1.03,a:4.0,d:1,s:0.006}];
    function C(){return W*0.6;} function Mid(){return H*0.5;} function RR(){return Math.min(W*0.72,H*1.15)*0.5;}
    function size(){DPR=Math.min(window.devicePixelRatio||1,2);W=cvs.clientWidth;H=cvs.clientHeight;cvs.width=W*DPR;cvs.height=H*DPR;cx2.setTransform(DPR,0,0,DPR,0,0);}
    function pulse(cxv,cyv,r,ang,dir){
      var N=36,span=1.15;
      cx2.save();cx2.shadowBlur=8;cx2.shadowColor='rgba('+CY+',0.6)';
      for(var k=N-1;k>=0;k--){var aa=ang-dir*(k/N)*span,al=(1-k/N);al*=al;
        cx2.beginPath();cx2.fillStyle='rgba('+CY+','+al+')';
        cx2.arc(cxv+Math.cos(aa)*r,cyv+Math.sin(aa)*r,al*2.6+0.4,0,6.2832);cx2.fill();}
      cx2.restore();
      var hx=cxv+Math.cos(ang)*r,hy=cyv+Math.sin(ang)*r;
      cx2.save();cx2.shadowBlur=22;cx2.shadowColor='rgba('+CY+',1)';
      cx2.beginPath();cx2.fillStyle='rgba(220,255,251,0.98)';cx2.arc(hx,hy,3.3,0,6.2832);cx2.fill();cx2.restore();
    }
    function draw(){
      cx2.clearRect(0,0,W,H);
      var cxv=C(),cyv=Mid(),R=RR(),i,g,j,n,p;
      var gl=cx2.createRadialGradient(cxv,cyv,R*0.1,cxv,cyv,R*1.25);
      gl.addColorStop(0,'rgba('+CY+',0.10)');gl.addColorStop(0.6,'rgba('+CY+',0.04)');gl.addColorStop(1,'rgba('+CY+',0)');
      cx2.fillStyle=gl;cx2.fillRect(0,0,W,H);
      cx2.lineWidth=1;
      for(i=0;i<14;i++){var ang=i/14*6.2832+T*0.04;
        cx2.beginPath();cx2.strokeStyle='rgba('+CY+',0.05)';
        cx2.moveTo(cxv+Math.cos(ang)*R*0.35,cyv+Math.sin(ang)*R*0.35);
        cx2.lineTo(cxv+Math.cos(ang)*R*1.12,cyv+Math.sin(ang)*R*1.12);cx2.stroke();}
      for(g=0;g<3;g++){cx2.beginPath();cx2.strokeStyle='rgba('+CY+',0.045)';cx2.arc(cxv,cyv,R*(1.12+g*0.14),0,6.2832);cx2.stroke();}
      for(j=0;j<rings.length;j++){cx2.beginPath();cx2.strokeStyle='rgba('+CY+','+rAlpha[j]+')';cx2.lineWidth=(j===1?1.4:1);cx2.arc(cxv,cyv,R*rings[j],0,6.2832);cx2.stroke();}
      for(n=0;n<8;n++){var na=n/8*6.2832+T*0.02,nr=R*rings[2];
        cx2.beginPath();cx2.fillStyle='rgba('+CY+',0.25)';cx2.arc(cxv+Math.cos(na)*nr,cyv+Math.sin(na)*nr,1.3,0,6.2832);cx2.fill();}
      for(p=0;p<pulses.length;p++){pulse(cxv,cyv,R*pulses[p].r,pulses[p].a,pulses[p].d);}
      cx2.save();cx2.shadowBlur=18;cx2.shadowColor='rgba('+CY+',0.7)';
      cx2.beginPath();cx2.fillStyle='rgba('+CY+',0.5)';cx2.arc(cxv,cyv,2.2,0,6.2832);cx2.fill();cx2.restore();
      var grd=cx2.createLinearGradient(0,0,W*0.62,0);
      grd.addColorStop(0,'rgba(0,0,0,1)');grd.addColorStop(1,'rgba(0,0,0,0)');
      cx2.globalCompositeOperation='destination-out';cx2.fillStyle=grd;cx2.fillRect(0,0,W*0.62,H);
      cx2.globalCompositeOperation='source-over';
    }
    function tick(){for(var p=0;p<pulses.length;p++){pulses[p].a+=pulses[p].s*pulses[p].d;}T++;draw();RAF=requestAnimationFrame(tick);}
    size();draw();
    if(!reduce)tick();
    var to;window.addEventListener('resize',function(){clearTimeout(to);to=setTimeout(function(){if(RAF)cancelAnimationFrame(RAF);size();draw();if(!reduce)tick();},180);});
  }

  /* появление при прокрутке (reveal) — «живой» сайт */
  if('IntersectionObserver' in window){
    var rsel='.band-head,.cat,.pcard,.level,.app,.adv .item,.why-list .wl,.step,.about-side,.table-wrap,.client,.pd-photo,.pd-desc,.pd-chips,.contact,.feat-list';
    var rio=new IntersectionObserver(function(es){es.forEach(function(en){if(en.isIntersecting){en.target.classList.add('in');rio.unobserve(en.target);}});},{threshold:0.08,rootMargin:'0px 0px -6% 0px'});
    [].slice.call(document.querySelectorAll(rsel)).forEach(function(el){
      el.classList.add('reveal');
      var prev=0,s=el.previousElementSibling; while(s){ if(s.classList&&s.classList.contains('reveal'))prev++; s=s.previousElementSibling; }
      el.style.transitionDelay=Math.min(prev,6)*50+'ms';
      rio.observe(el);
    });
  }
})();
